    (34, 'fead42ae-fdd5-48d1-bcc9-567c1c7873b8'::uuid, 'Denbury Hill Fort - Earthworks - geograph.org.uk - 2350383.webp', 'https://upload.wikimedia.org/wikipedia/commons/a/a3/Denbury_Hill_Fort_-_Earthworks_-_geograph.org.uk_-_2350383.jpg', 'https://commons.wikimedia.org/wiki/File%3ADenbury%20Hill%20Fort%20-%20Earthworks%20-%20geograph.org.uk%20-%202350383.jpg', 'Denbury Hill Fort - Earthworks - geograph.org.uk - 2350383', 'Colin Vosper', 'https://www.geograph.org.uk/profile/19916', 'CC BY-SA 2.0', 'https://creativecommons.org/licenses/by-sa/2.0', 1600, 1200, 865734, 107486, '/data/images/wiki/fead42ae/East-Facing_View_of_Denbury_Down.webp', '/data/images/wiki/fead42ae/Denbury Hill Fort - Earthworks - geograph.org.uk - 2350383.webp', 'import-hero/insert:fead42ae-fdd5-48d1-bcc9-567c1c7873b8', 'the 2025 import links this file for the site and no row of it holds the file; the owner''s decision of 2026-10-05 (17:43) is that the import''s image is the hero', '[{"quote": "https://upload.wikimedia.org/wikipedia/commons/a/a3/Denbury_Hill_Fort_-_Earthworks_-_geograph.org.uk_-_2350383.jpg", "source": "the 2025 import''s own link (ancient_nerds_original.geojson)", "url": "https://commons.wikimedia.org/wiki/File%3ADenbury%20Hill%20Fort%20-%20Earthworks%20-%20geograph.org.uk%20-%202350383.jpg"}, {"quote": "3 row(s) of this site, none holding https://upload.wikimedia.org/wikipedia/commons/a/a3/Denbury_Hill_Fort_-_Earthworks_-_geograph.org.uk_-_2350383.jpg", "source": "the plan''s read of production", "url": "wiki_images WHERE site_id = fead42ae-fdd5-48d1-bcc9-567c1c7873b8"}]'::jsonb),
    (35, 'ff1c4702-9115-43fc-b64f-15a9729bc6d9'::uuid, 'Kharkhorum Museum in Kharkhorin, Mongolia.webp', 'https://upload.wikimedia.org/wikipedia/commons/f/f2/Kharkhorum_Museum_in_Kharkhorin%2C_Mongolia.jpg', 'https://commons.wikimedia.org/wiki/File%3AKharkhorum%20Museum%20in%20Kharkhorin%2C%20Mongolia.jpg', 'Kharkhorum Museum in Kharkhorin, Mongolia', 'Batu', 'https://commons.wikimedia.org/wiki/User:Batu', 'CC BY-SA 3.0', 'https://creativecommons.org/licenses/by-sa/3.0', 1600, 1200, 139260, 107575, '/data/images/wiki/ff1c4702/hero.webp', '/data/images/wiki/ff1c4702/Kharkhorum Museum in Kharkhorin, Mongolia.webp', 'import-hero/insert:ff1c4702-9115-43fc-b64f-15a9729bc6d9', 'the 2025 import links this file for the site and no row of it holds the file; the owner''s decision of 2026-10-05 (17:43) is that the import''s image is the hero', '[{"quote": "https://upload.wikimedia.org/wikipedia/commons/f/f2/Kharkhorum_Museum_in_Kharkhorin%2C_Mongolia.jpg", "source": "the 2025 import''s own link (ancient_nerds_original.geojson)", "url": "https://commons.wikimedia.org/wiki/File%3AKharkhorum%20Museum%20in%20Kharkhorin%2C%20Mongolia.jpg"}, {"quote": "20 row(s) of this site, none holding https://upload.wikimedia.org/wikipedia/commons/f/f2/Kharkhorum_Museum_in_Kharkhorin%2C_Mongolia.jpg", "source": "the plan''s read of production", "url": "wiki_images WHERE site_id = ff1c4702-9115-43fc-b64f-15a9729bc6d9"}]'::jsonb),
    (36, 'ff3dcd2e-6e3b-405b-a532-09b7cf71dff0'::uuid, 'Sarcófagos de Karajía-1.webp', 'https://upload.wikimedia.org/wikipedia/commons/4/44/Sarc%C3%B3fagos_de_Karaj%C3%ADa-1.jpg', 'https://commons.wikimedia.org/wiki/File%3ASarc%C3%B3fagos%20de%20Karaj%C3%ADa-1.jpg', 'Sarcófagos de Karajía-1', 'PsamatheM', 'https://commons.wikimedia.org/wiki/User:PsamatheM', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 1600, 1067, 632674, 107613, '/data/images/wiki/ff3dcd2e/Karajía, 2023 (01).webp', '/data/images/wiki/ff3dcd2e/Sarcófagos de Karajía-1.webp', 'import-hero/insert:ff3dcd2e-6e3b-405b-a532-09b7cf71dff0', 'the 2025 import links this file for the site and no row of it holds the file; the owner''s decision of 2026-10-05 (17:43) is that the import''s image is the hero', '[{"quote": "https://upload.wikimedia.org/wikipedia/commons/4/44/Sarc%C3%B3fagos_de_Karaj%C3%ADa-1.jpg", "source": "the 2025 import''s own link (ancient_nerds_original.geojson)", "url": "https://commons.wikimedia.org/wiki/File%3ASarc%C3%B3fagos%20de%20Karaj%C3%ADa-1.jpg"}, {"quote": "20 row(s) of this site, none holding https://upload.wikimedia.org/wikipedia/commons/4/44/Sarc%C3%B3fagos_de_Karaj%C3%ADa-1.jpg", "source": "the plan''s read of production", "url": "wiki_images WHERE site_id = ff3dcd2e-6e3b-405b-a532-09b7cf71dff0"}]'::jsonb),
    (37, 'ff76a431-09d7-40b4-8dc5-b80211b2e246'::uuid, 'Σαγράδα Φαμίλια 2941 (cropped).webp', 'https://upload.wikimedia.org/wikipedia/commons/2/26/%CE%A3%CE%B1%CE%B3%CF%81%CE%AC%CE%B4%CE%B1_%CE%A6%CE%B1%CE%BC%CE%AF%CE%BB%CE%B9%CE%B1_2941.jpg', 'https://commons.wikimedia.org/wiki/File%3A%CE%A3%CE%B1%CE%B3%CF%81%CE%AC%CE%B4%CE%B1%20%CE%A6%CE%B1%CE%BC%CE%AF%CE%BB%CE%B9%CE%B1%202941%20%28cropped%29.jpg', 'Σαγράδα Φαμίλια 2941 (cropped)', 'C messier', 'https://commons.wikimedia.org/wiki/User:C_messier', 'CC BY-SA 4.0', 'https://creativecommons.org/licenses/by-sa/4.0', 1600, 2364, 721520, 107698, '/data/images/wiki/ff76a431/Muralla_Raval.webp', '/data/images/wiki/ff76a431/Σαγράδα Φαμίλια 2941 (cropped).webp', 'import-hero/insert:ff76a431-09d7-40b4-8dc5-b80211b2e246', 'the 2025 import links this file for the site and no row of it holds the file; the owner''s decision of 2026-10-05 (17:43) is that the import''s image is the hero', '[{"quote": "https://upload.wikimedia.org/wikipedia/commons/2/26/%CE%A3%CE%B1%CE%B3%CF%81%CE%AC%CE%B4%CE%B1_%CE%A6%CE%B1%CE%BC%CE%AF%CE%BB%CE%B9%CE%B1_2941.jpg", "source": "the 2025 import''s own link (ancient_nerds_original.geojson)", "url": "https://commons.wikimedia.org/wiki/File%3A%CE%A3%CE%B1%CE%B3%CF%81%CE%AC%CE%B4%CE%B1%20%CE%A6%CE%B1%CE%BC%CE%AF%CE%BB%CE%B9%CE%B1%202941%20%28cropped%29.jpg"}, {"quote": "20 row(s) of this site, none holding https://upload.wikimedia.org/wikipedia/commons/2/26/%CE%A3%CE%B1%CE%B3%CF%81%CE%AC%CE%B4%CE%B1_%CE%A6%CE%B1%CE%BC%CE%AF%CE%BB%CE%B9%CE%B1_2941.jpg", "source": "the plan''s read of production", "url": "wiki_images WHERE site_id = ff76a431-09d7-40b4-8dc5-b80211b2e246"}]'::jsonb);

DO $$
DECLARE
    bad  integer;
    r    RECORD;
    new_id integer;
    cols TEXT;
BEGIN
    -- guard 1: every planned site is a curated site (the message names the source in words, so
    -- the log of a refused wave says what was expected)
    SELECT count(*) INTO bad FROM (SELECT DISTINCT site_id FROM _ih_insert) p
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        RAISE EXCEPTION '%: % planned site(s) are not ancient_nerds sites',
            'import-hero-2026-10-06-006-002', bad;
    END IF;

    FOR r IN SELECT * FROM _ih_insert ORDER BY seq LOOP
        -- guard 2: no row of this site holds the file yet. The unique constraint on
        -- (site_id, original_url) is a second line of defence behind this one.
        IF EXISTS (SELECT 1 FROM wiki_images w
                    WHERE w.site_id = r.site_id AND w.original_url = r.original_url) THEN
            RAISE EXCEPTION '%: site % already holds this file', r.change_key, r.site_id;
        END IF;

        -- guard 3: the file reaches the hero floor
        IF r.width < 1600 OR r.height < 900 THEN
            RAISE EXCEPTION '%: the file is %x%, under the %x% this lane serves', r.change_key,
                r.width, r.height, 1600, 900;
        END IF;

        -- guard 4: the row that holds the flag is still the one the plan demotes
        IF r.demoted_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM wiki_images w
             WHERE w.id = r.demoted_id AND w.site_id = r.site_id AND w.is_hero) THEN
            RAISE EXCEPTION '%: the row that held the flag for site % moved since the read',
                r.change_key, r.site_id;
        END IF;

        -- guard 5: the thumbnail still holds the value the read found
        IF (SELECT u.thumbnail_url FROM unified_sites u WHERE u.id = r.site_id)
           IS DISTINCT FROM r.old_thumbnail THEN
            RAISE EXCEPTION '%: the thumbnail of site % moved since the read', r.change_key, r.site_id;
        END IF;

        -- the row that gives up the flag, and the row that takes it
        IF r.demoted_id IS NOT NULL THEN
            UPDATE wiki_images SET is_hero = false
             WHERE id = r.demoted_id AND is_hero AND site_id = r.site_id;
        END IF;

        -- the three columns the file does not carry: the next free number of this site (derived,
        -- never invented), the owner's picture rather than a measured lead image of the article,
        -- and the source 49,683 of the 49,691 curated rows carry
        INSERT INTO wiki_images
            (site_id, filename, original_url, commons_page_url, title, author, author_url, license, license_url, width, height, file_size_bytes, is_lead, sort_order, source_type, is_hero, is_excluded)
        SELECT r.site_id, r.filename, r.original_url, r.commons_page_url, r.title, r.author, r.author_url, r.license, r.license_url, r.width, r.height, r.file_size_bytes, false,
               (SELECT COALESCE(MAX(w2.sort_order), -1) + 1 FROM wiki_images w2
                 WHERE w2.site_id = r.site_id),
               'wikimedia', true, false
        RETURNING id INTO new_id;

        IF r.new_thumbnail IS DISTINCT FROM r.old_thumbnail THEN
            UPDATE unified_sites SET thumbnail_url = r.new_thumbnail WHERE id = r.site_id;
        END IF;

        -- the journal, in this transaction: one row per column this statement wrote,
        -- read back from the row it created, so the journal records what the database holds
        INSERT INTO remediation_change_log
            (run_stamp, test_id, table_name, column_name, row_pk, old_value, new_value, change_key,
             confidence, evidence, site_id_ref)
        SELECT 'import-hero-2026-10-06-006-002', 'import-hero/insert/owner-2026-10-05', 'wiki_images', t.col, new_id::text, NULL, t.val,
               r.change_key || ':' || t.col, 'authoritative', r.evidence, r.site_id
          FROM wiki_images w
          CROSS JOIN LATERAL (VALUES
              ('filename', w.filename::text),
              ('original_url', w.original_url::text),
              ('commons_page_url', w.commons_page_url::text),
              ('title', w.title::text),
              ('author', w.author::text),
              ('author_url', w.author_url::text),
              ('license', w.license::text),
              ('license_url', w.license_url::text),
              ('width', w.width::text),
              ('height', w.height::text),
              ('file_size_bytes', w.file_size_bytes::text),
              ('is_lead', w.is_lead::text),
              ('sort_order', w.sort_order::text),
              ('source_type', w.source_type::text)
          ) AS t(col, val)
         WHERE w.id = new_id;

        IF r.demoted_id IS NOT NULL THEN
            INSERT INTO remediation_change_log
                (run_stamp, test_id, table_name, column_name, row_pk, old_value, new_value,
                 change_key, confidence, evidence, site_id_ref)
            VALUES ('import-hero-2026-10-06-006-002', 'import-hero/insert/owner-2026-10-05', 'wiki_images', 'is_hero',
                    r.demoted_id::text, 'true', 'false', r.change_key || ':demote',
                    'authoritative', r.evidence, r.site_id);
        END IF;

        IF r.new_thumbnail IS DISTINCT FROM r.old_thumbnail THEN
            INSERT INTO remediation_change_log
                (run_stamp, test_id, table_name, column_name, row_pk, old_value, new_value,
                 change_key, confidence, evidence, site_id_ref)
            VALUES ('import-hero-2026-10-06-006-002', 'import-hero/insert/owner-2026-10-05', 'unified_sites', 'thumbnail_url',
                    r.site_id::text, r.old_thumbnail, r.new_thumbnail,
                    r.change_key || ':thumbnail', 'authoritative', r.evidence, r.site_id);
        END IF;
    END LOOP;

    -- invariant 1: every planned row stands, with the planned values, the flag and the three
    -- columns the statement derived for it. The temp table is aliased `p`, never `r`: the loop
    -- variable of this block is `r`, and Postgres refuses a reference that could mean either
    -- (measured 2026-10-06, in the rehearsal of chunk-001).
    SELECT count(*) INTO bad FROM _ih_insert p
      LEFT JOIN wiki_images w ON w.site_id = p.site_id AND w.original_url = p.original_url
     WHERE w.id IS NULL OR w.is_hero IS NOT TRUE OR w.is_excluded IS NOT FALSE
        OR w.width IS DISTINCT FROM p.width OR w.height IS DISTINCT FROM p.height
        OR w.file_size_bytes IS DISTINCT FROM p.file_size_bytes
        OR w.filename IS DISTINCT FROM p.filename OR w.original_url IS DISTINCT FROM p.original_url
        OR w.is_lead IS NOT FALSE OR w.source_type IS DISTINCT FROM 'wikimedia'
        OR w.sort_order <> (SELECT COALESCE(MAX(w3.sort_order), 0) FROM wiki_images w3
                             WHERE w3.site_id = p.site_id);
    IF bad > 0 THEN
        RAISE EXCEPTION '%: % inserted row(s) do not stand as planned', 'import-hero-2026-10-06-006-002', bad;
    END IF;

    -- invariant 2: at most one live hero per touched site (T09's invariant)
    SELECT count(*) INTO bad FROM (
        SELECT w.site_id FROM wiki_images w
          JOIN _ih_insert p ON p.site_id = w.site_id
         WHERE w.is_hero AND w.is_excluded IS NOT TRUE
         GROUP BY w.site_id HAVING count(*) > 1) d;
    IF bad > 0 THEN
        RAISE EXCEPTION '%: % touched site(s) hold more than one live hero row',
            'import-hero-2026-10-06-006-002', bad;
    END IF;

    -- invariant 3: the journal carries every write, and nothing else
    SELECT count(*) INTO bad FROM _ih_insert p
      LEFT JOIN (SELECT site_id_ref, count(*) AS n FROM remediation_change_log
                  WHERE run_stamp = 'import-hero-2026-10-06-006-002' GROUP BY site_id_ref) l
        ON l.site_id_ref = p.site_id
     WHERE COALESCE(l.n, 0) <> 14
        + CASE WHEN p.demoted_id IS NOT NULL THEN 1 ELSE 0 END
        + CASE WHEN p.new_thumbnail IS DISTINCT FROM p.old_thumbnail THEN 1 ELSE 0 END;
    IF bad > 0 THEN
        RAISE EXCEPTION '%: % site(s) do not have exactly their planned journal rows',
            'import-hero-2026-10-06-006-002', bad;
    END IF;
END $$;

-- the same two read-back lines the shared writer ends with, so `--rehearse` recognises the run
SELECT 'journal rows for this run', count(*)::text FROM remediation_change_log WHERE run_stamp = 'import-hero-2026-10-06-006-002';
SELECT 'planned rows', count(*)::text FROM _ih_insert;
COMMIT;
